//! Types and pure helpers shared by native Rust tests and CLVM compilation.
//!
//! Nominal types prevent source-level domain swaps. Their public constructors
//! establish no cryptographic or protocol invariant. The CLVM ABI validates the
//! inner representation, not a runtime nominal tag or constructor predicate.
#![no_std]

#[cfg(feature = "alloc")]
extern crate alloc;

pub use chialisp_oxide_macros::puzzle;

mod domain;
pub use domain::*;

mod tree;
pub use tree::*;

#[cfg(feature = "alloc")]
mod owned_tree;
#[cfg(feature = "alloc")]
pub use owned_tree::*;

mod hashing;
pub use hashing::{sha256, sha256_parts};

//! Immutable CLVM data, with ordinary Rust lifetimes and pattern matching.
//!
//! A tree carries its original atom bytes. Numeric padding, improper pairs and
//! arbitrary tails are data; this type does not interpret or normalize them.
//! The compiler supports direct recursive traversal of this restricted shape.
//! The opt-in `alloc` feature adds `OwnedTree` for restricted owned
//! pair construction. General enums, mutable references, pointer/allocator APIs,
//! and general runtime program evaluation remain outside the supported subset.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Tree<'a> {
    Atom(&'a [u8]),
    Pair(&'a Tree<'a>, &'a Tree<'a>),
}

/// CLVM's quote operator as data, for constructing a quoted program.
pub const QUOTE: Tree<'static> = Tree::Atom(&[1]);

/// Construct a program returning `value` when applied to any environment.
///
/// This is an ordinary Rust function. The compiler checks and lowers its MIR;
/// its name does not grant it intrinsic semantics.
pub fn quote<'a>(value: &'a Tree<'a>) -> Tree<'a> {
    Tree::Pair(&QUOTE, value)
}

#![forbid(unsafe_code)]
//! Exact atom-payload hashing for native tests and the reviewed compiler bridge.
//! This module does not establish authorization, domain separation or security.

/// SHA256 of the exact bytes, returning all 32 digest bytes, including zeros.
///
/// No integer, UTF-8, hexadecimal or CLVM serialization conversion is performed.
pub fn sha256(bytes: &[u8]) -> [u8; 32] {
    sha256_parts(bytes, &[], &[])
}

/// Scalar SHA-256 of the exact concatenation a || b || c.
///
/// Native kernel for the prototype compiler bridge; not a verified implementation.
/// Byte/block positions use u128: three usize lengths plus SHA padding fit even
/// on a 64-bit target. FIPS 180-4 defines SHA-256 for messages below 2^64 bits;
/// this implementation encodes the low 64 bits of the bit length explicitly.
/// No allocation, helper/trait calls, architecture dispatch or wrapping methods.
// Keep the reviewed scalar operations explicit: rotate/div_ceil methods would
// change the closed MIR call graph that the compiler bridge matches.
#[allow(clippy::manual_rotate, clippy::manual_div_ceil)]
pub fn sha256_parts(a: &[u8], b: &[u8], c: &[u8]) -> [u8; 32] {
    const K: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4,
        0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,
        0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
        0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
        0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
        0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
        0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116,
        0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
        0xc67178f2,
    ];
    let mut h: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
        0x5be0cd19,
    ];
    let a_len = a.len() as u128;
    let ab_len = a_len + b.len() as u128;
    let message_len = ab_len + c.len() as u128;
    let bit_len = (message_len << 3) as u64;
    let padded_len = ((message_len + 9 + 63) / 64) * 64;
    let mut block_start = 0u128;
    while block_start < padded_len {
        let mut w = [0u32; 64];
        let mut i = 0usize;
        while i < 64 {
            let position = block_start + i as u128;
            let byte = if position < a_len {
                a[position as usize]
            } else if position < ab_len {
                b[(position - a_len) as usize]
            } else if position < message_len {
                c[(position - ab_len) as usize]
            } else if position == message_len {
                0x80
            } else if position >= padded_len - 8 {
                (bit_len >> ((padded_len - 1 - position) as u32 * 8)) as u8
            } else {
                0
            };
            let word = i / 4;
            w[word] = (w[word] << 8) | byte as u32;
            i += 1;
        }
        i = 16;
        while i < 64 {
            let x = w[i - 15];
            let y = w[i - 2];
            let small0 = ((x >> 7) | (x << 25)) ^ ((x >> 18) | (x << 14)) ^ (x >> 3);
            let small1 = ((y >> 17) | (y << 15)) ^ ((y >> 19) | (y << 13)) ^ (y >> 10);
            w[i] = (w[i - 16] as u64 + small0 as u64 + w[i - 7] as u64 + small1 as u64) as u32;
            i += 1;
        }
        let mut aa = h[0];
        let mut bb = h[1];
        let mut cc = h[2];
        let mut dd = h[3];
        let mut ee = h[4];
        let mut ff = h[5];
        let mut gg = h[6];
        let mut hh = h[7];
        i = 0;
        while i < 64 {
            let big1 =
                ((ee >> 6) | (ee << 26)) ^ ((ee >> 11) | (ee << 21)) ^ ((ee >> 25) | (ee << 7));
            let choose = (ee & ff) ^ (!ee & gg);
            let temp1 =
                (hh as u64 + big1 as u64 + choose as u64 + K[i] as u64 + w[i] as u64) as u32;
            let big0 =
                ((aa >> 2) | (aa << 30)) ^ ((aa >> 13) | (aa << 19)) ^ ((aa >> 22) | (aa << 10));
            let majority = (aa & bb) ^ (aa & cc) ^ (bb & cc);
            let temp2 = (big0 as u64 + majority as u64) as u32;
            hh = gg;
            gg = ff;
            ff = ee;
            ee = (dd as u64 + temp1 as u64) as u32;
            dd = cc;
            cc = bb;
            bb = aa;
            aa = (temp1 as u64 + temp2 as u64) as u32;
            i += 1;
        }
        h[0] = (h[0] as u64 + aa as u64) as u32;
        h[1] = (h[1] as u64 + bb as u64) as u32;
        h[2] = (h[2] as u64 + cc as u64) as u32;
        h[3] = (h[3] as u64 + dd as u64) as u32;
        h[4] = (h[4] as u64 + ee as u64) as u32;
        h[5] = (h[5] as u64 + ff as u64) as u32;
        h[6] = (h[6] as u64 + gg as u64) as u32;
        h[7] = (h[7] as u64 + hh as u64) as u32;
        block_start += 64;
    }
    let mut digest = [0u8; 32];
    let mut i = 0usize;
    while i < 32 {
        digest[i] = (h[i / 4] >> (24 - (i % 4) * 8)) as u8;
        i += 1;
    }
    digest
}

#[cfg(test)]
mod tests {
    use super::{sha256, sha256_parts};

    #[test]
    fn known_answers_and_exact_multipart_payloads() {
        let empty = [
            0xe3, 0xb0, 0xc4, 0x42, 0x98, 0xfc, 0x1c, 0x14, 0x9a, 0xfb, 0xf4, 0xc8, 0x99, 0x6f,
            0xb9, 0x24, 0x27, 0xae, 0x41, 0xe4, 0x64, 0x9b, 0x93, 0x4c, 0xa4, 0x95, 0x99, 0x1b,
            0x78, 0x52, 0xb8, 0x55,
        ];
        let abc = [
            0xba, 0x78, 0x16, 0xbf, 0x8f, 0x01, 0xcf, 0xea, 0x41, 0x41, 0x40, 0xde, 0x5d, 0xae,
            0x22, 0x23, 0xb0, 0x03, 0x61, 0xa3, 0x96, 0x17, 0x7a, 0x9c, 0xb4, 0x10, 0xff, 0x61,
            0xf2, 0x00, 0x15, 0xad,
        ];
        assert_eq!(sha256(b""), empty);
        assert_eq!(sha256_parts(b"", b"", b""), empty);
        assert_eq!(sha256(b"abc"), abc);
        assert_eq!(sha256_parts(b"a", b"b", b"c"), abc);
        assert_eq!(sha256_parts(b"", b"abc", b""), abc);
        assert_ne!(sha256(b""), sha256(b"\0"));
        assert_ne!(sha256(b"\x01"), sha256(b"\0\x01"));
    }
}

"""Independent finite expected recipes and mathematical expected relation.

No Rust/Rue compiler or CLVM VM is called. Opaque prehash leaves deliberately
retain arbitrary byte widths because the original legacy helper validates none.
This model is not a hash security or compiler-preservation proof.
"""
from dataclasses import dataclass
import hashlib
import json
from pathlib import Path


@dataclass(frozen=True)
class Prehashed:
    payload: bytes


def proper(*items):
    result = b""
    for item in reversed(items):
        result = item, result
    return result


def tree_hash(tree):
    if isinstance(tree, Prehashed):
        return tree.payload
    if isinstance(tree, bytes):
        return hashlib.sha256(b"\x01" + tree).digest()
    first, rest = tree
    return hashlib.sha256(b"\x02" + tree_hash(first) + tree_hash(rest)).digest()


def curry(module, arguments):
    environment = b"\x01"
    for argument in reversed(arguments):
        environment = proper(b"\x04", (b"\x01", argument), environment)
    return proper(b"\x02", (b"\x01", module), environment)


def expected(tree):
    fields = []
    for _ in range(5):
        if not isinstance(tree, tuple):
            return {"status": "rejected"}
        fields.append(tree[0])
        tree = tree[1]
    module_hash, launcher_id, launcher_puzzle_hash, inner_hash, my_id = fields
    if not all(isinstance(value, bytes) for value in [module_hash, inner_hash, my_id]):
        return {"status": "rejected"}
    singleton_struct = module_hash, (launcher_id, launcher_puzzle_hash)
    # Construct the standard program SHAPE instead of copying the source's
    # expanded hash-update formulas. Supplied digests are opaque hash leaves.
    full_hash = tree_hash(curry(Prehashed(module_hash), [singleton_struct, Prehashed(inner_hash)]))
    announcement_name = hashlib.sha256(full_hash + my_id).digest()
    output = proper(proper(b"\x3f", announcement_name), proper(b"\x3c", b"$"), proper(b"\x46", my_id))
    return {"status": "accepted", "output_hex": serialize(output).hex()}


def serialize(tree):
    if isinstance(tree, tuple):
        return b"\xff" + serialize(tree[0]) + serialize(tree[1])
    size = len(tree)
    if size == 0:
        return b"\x80"
    if size == 1 and tree[0] < 0x80:
        return tree
    for limit, prefix, width in [(0x40, 0x80, 1), (0x2000, 0xc0, 2), (0x100000, 0xe0, 3), (0x8000000, 0xf0, 4)]:
        if size < limit:
            return bytes([prefix | (size >> (8 * (width - 1)))]) + size.to_bytes(width, "big")[1:] + tree
    raise ValueError("research atom exceeds codec bound")


def deserialize(data):
    def read(offset):
        first = data[offset]
        offset += 1
        if first == 0xff:
            left, offset = read(offset)
            right, offset = read(offset)
            return (left, right), offset
        if first < 0x80:
            return bytes([first]), offset
        if first < 0xc0:
            size, width = first & 0x3f, 1
        elif first < 0xe0:
            size, width = first & 0x1f, 2
        elif first < 0xf0:
            size, width = first & 0x0f, 3
        elif first < 0xf8:
            size, width = first & 7, 4
        else:
            raise ValueError("unsupported research serialization prefix")
        for _ in range(width - 1):
            size = (size << 8) | data[offset]
            offset += 1
        end = offset + size
        if end > len(data):
            raise ValueError("truncated atom")
        return data[offset:end], end
    tree, end = read(0)
    if end != len(data):
        raise ValueError("trailing bytes")
    return tree


def display(tree):
    if isinstance(tree, bytes):
        return "()" if tree == b"" else "0x" + tree.hex()
    return "(" + display(tree[0]) + " . " + display(tree[1]) + ")"


def environment(fields, tail=b""):
    result = tail
    for value in reversed(fields):
        result = value, result
    return result


def named():
    base = [bytes([tag]) * 32 for tag in [0x11, 0x22, 0x33, 0x44, 0x55]]
    rows = [("ordinary five32-byte fields", proper(*base)), ("nil hash fields remain valid raw atoms", proper(*([b""] * 5)))]
    for index, name in [(0, "module prehash"), (3, "inner prehash"), (4, "coin id")]:
        for width in [0, 31, 33, 8192]:
            fields = base.copy()
            fields[index] = bytes((17 * j + index) & 255 for j in range(width))
            rows.append((f"{name} width{width} is not narrowed", proper(*fields)))
        for payload in [b"\0", b"\0\0", b"\0\x01"]:
            fields = base.copy()
            fields[index] = payload
            rows.append((f"{name} preserves atom{payload.hex()}", proper(*fields)))
    trees = [b"", b"\0", (b"\x01", b"\x02"), proper(b"\x08"), (proper(b"\0\x01"), b"\0\0")]
    for index, name in [(1, "launcher id"), (2, "launcher puzzle hash")]:
        for ordinal, value in enumerate(trees):
            fields = base.copy()
            fields[index] = value
            rows.append((f"{name} arbitrary tree{ordinal}", proper(*fields)))
    for label, tail in [("nonemptyzero", b"\0"), ("padding", b"\0\0"), ("extra field", proper(b"ignored")), ("program data", (b"\x08", b"\0"))]:
        rows.append(("ignored tail " + label, environment(base, tail)))
    for count in range(5):
        rows.append((f"missing field{count + 1}", proper(*base[:count])))
    for index, name in [(0, "module prehash"), (3, "inner prehash"), (4, "coin id")]:
        fields = base.copy()
        fields[index] = (b"\x01", b"\x02")
        rows.append((name + " pair rejects", proper(*fields)))
    for index, name in [(1, "launcher id"), (2, "launcher puzzle hash")]:
        nested = b"\0\x01"
        for _ in range(128):
            nested = b"\0", nested
        fields = base.copy()
        fields[index] = nested
        rows.append((name + " deep arbitrary tree", proper(*fields)))
    rows.extend([("bare nonemptyzero", b"\0"), ("truncated improper environment", environment(base[:3], b"\0\0"))])
    fields = base.copy()
    fields[4] = b"\xff"
    rows.append(("negative-looking my id stays raw bytes", proper(*fields)))
    return rows


def generated():
    widths = [0, 1, 2, 31, 32, 33, 55, 56, 63, 64, 65, 255]
    rows = []
    for index in range(128):
        fields = [bytes((17 * index + 31 * field + offset) & 255 for offset in range(widths[(index + field) % len(widths)])) for field in range(5)]
        fields[1] = fields[1], (b"\0", fields[2])
        if index % 4 == 3:
            fields[[0, 3, 4][(index // 4) % 3]] = proper(b"\x08")
        tail = [b"", b"\0", b"\0\0", proper(b"extra")][index % 4]
        rows.append((f"deterministic raw fields{index}", environment(fields, tail)))
    return rows


def records(rows):
    return [{"label": label, "solution": display(tree), "input_hex": serialize(tree).hex(),
             "expected": expected(tree)} for label, tree in rows]


def check_expected_relations():
    here = Path(__file__).resolve().parent
    binary = bytes.fromhex((here.parents[1] / "corpus/upstream/chia-puzzles/cfe5ced68af8b5e9d5e2cc66071bbe6497f9eda8/puzzles/p2_singleton.clsp.hex").read_text())
    tree = deserialize(binary)
    assert serialize(tree) == binary and len(binary) == 403
    assert tree_hash(tree).hex() == "40f828d8dd55603f4ff9fbf6b73271e904e69406982f4fbefae2c8dcceaf9834"
    # Independent shape model agrees with materialized trees when prehashes
    # actually come from known programs. No VM or source compiler is involved.
    module, inner = proper(b"\x01", b"module data"), proper(b"\x01", b"inner data")
    fields = [tree_hash(module), (b"\0\x01", b"\0"), proper(b"\x08"), tree_hash(inner), b"\xff"]
    singleton_struct = fields[0], (fields[1], fields[2])
    assert tree_hash(curry(Prehashed(fields[0]), [singleton_struct, Prehashed(fields[3])])) == tree_hash(curry(module, [singleton_struct, inner]))
    for _, tree in named() + generated():
        assert deserialize(serialize(tree)) == tree
    return {"named": len(named()), "generated": len(generated()), "status": "expected_relation_codec_and_hash_arithmetic_no_VM_invocation"}


